+  }
+}
+</script>
+<script type="module">
+import * as THREE from 'three';
+import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
+import { CSS2DRenderer, CSS2DObject } from 'three/addons/renderers/CSS2DRenderer.js';
+import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
+import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
+
+const HOT = '#ff5ea8';
+const WARM = '#ff9a86';
+const LIQ = '#3ecfb8';
+const COLD = '#5c7cff';
+const VAP = '#c3b0ff';
+
+const CAMS = {
+  wide: { p: [3.05, 2.05, 5.75], t: [0.15, 1.08, 0.0] },
+  loop: { p: [2.15, 1.62, 4.15], t: [0.25, 1.25, 0.0] },
+  coils: { p: [1.35, 1.72, 3.35], t: [0.1, 1.35, 0.0] },
+  machine: { p: [1.72, 0.78, 2.05], t: [1.22, 0.46, 0.02] },
+  heat: { p: [2.45, 1.55, 4.35], t: [0.35, 1.15, 0.0] },
+  mono: { p: [1.25, 1.05, 3.05], t: [-0.28, 0.68, 0.0] },
+};
+
+const STEPS = [
+  { system: 'split', mode: 'cool', cam: 'wide', text: 'An air conditioner moves heat. It does not create cold.' },
+  { system: 'split', mode: 'cool', cam: 'loop', text: 'Refrigerant travels a sealed loop. Room air and outdoor air never mix.' },
+  { system: 'split', mode: 'cool', cam: 'coils', text: 'Cooling: the indoor coil absorbs heat and condenses moisture. The outdoor coil releases that heat.' },
+  { system: 'split', mode: 'cool', cam: 'machine', text: 'The compressor raises pressure and temperature. The expansion device drops both before the coil that absorbs heat.' },
+  { system: 'split', mode: 'heat', cam: 'heat', text: 'Heating: the reversing valve swaps the coils. Heat is taken from outdoor air and released indoors.' },
+  { system: 'mono', mode: 'cool', cam: 'mono', text: 'Monoblock: the whole circuit sits indoors. Outdoor air enters and leaves through separate wall ducts.' },
+];
+
+const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
+let reduced = mq.matches;
+let system = 'split';
+let mode = 'cool';
+let playing = !reduced;
+let tourAuto = !reduced;
+let tourIndex = 0;
+let tourElapsed = 0;
+let viewMode = reduced ? 'home' : 'tour';
+let applying = false;
