+let tween = null;
+let heatAcc = 0;
+
+const shown = { indoor: 25.6, outdoor: 33.1, supply: 14.8, exhaust: 42.7 };
+const goal = { ...shown };
+
+const _p = new THREE.Vector3();
+const _t = new THREE.Vector3();
+const _n1 = new THREE.Vector3();
+const _n2 = new THREE.Vector3();
+const _up = new THREE.Vector3(0, 1, 0);
+const _c = new THREE.Color();
+const _a = new THREE.Vector3();
+const _b = new THREE.Vector3();
+const _cam = new THREE.Vector3();
+const _dummy = new THREE.Object3D();
+
+class PolylineCurve extends THREE.Curve {
+  constructor(points) {
+    super();
+    this.points = points.map((p) => p.clone());
+    this.lens = [0];
+    for (let i = 1; i < this.points.length; i++) {
+      const d = Math.max(1e-4, this.points[i].distanceTo(this.points[i - 1]));
+      this.lens.push(this.lens[i - 1] + d);
+    }
+    this.total = this.lens[this.lens.length - 1];
+    this.colors = this.points.map(() => new THREE.Color(0xffffff));
+    this.inletCount = 1;
+  }
+  getPoint(t, optionalTarget = new THREE.Vector3()) {
+    const d = THREE.MathUtils.clamp(t, 0, 1) * this.total;
+    let i = 1;
+    const n = this.lens.length;
+    while (i < n - 1 && this.lens[i] < d) i++;
+    const span = this.lens[i] - this.lens[i - 1];
+    const u = span > 0 ? (d - this.lens[i - 1]) / span : 0;
+    return optionalTarget.lerpVectors(this.points[i - 1], this.points[i], THREE.MathUtils.clamp(u, 0, 1));
+  }
+  tangentAt(t, target) {
+    const e = 0.015;
+    this.getPoint(Math.max(0, t - e), _a);
+    this.getPoint(Math.min(1, t + e), _b);
+    target.subVectors(_b, _a);
+    if (target.lengthSq() < 1e-8) target.set(0, 1, 0);
+    else target.normalize();
+    return target;
+  }
+  colorAt(t, target) {
+    const d = THREE.MathUtils.clamp(t, 0, 1) * this.total;
+    let i = 1;
+    const n = this.lens.length;
+    while (i < n - 1 && this.lens[i] < d) i++;
+    const span = this.lens[i] - this.lens[i - 1];
+    const u = span > 0 ? (d - this.lens[i - 1]) / span : 0;
+    return target.copy(this.colors[i - 1]).lerp(this.colors[i], THREE.MathUtils.clamp(u, 0, 1));
+  }
+}
+
+function smoothstep(t) {
+  const x = Math.min(1, Math.max(0, t));
+  return x * x * (3 - 2 * x);
+}
+
+function std(color, roughness, metalness, extra) {
+  return new THREE.MeshStandardMaterial({ color, roughness, metalness, ...extra });
+}
+
+function setText(el, text) {
+  if (el && el.textContent !== text) el.textContent = text;
+}
+
+function showFallback(msg) {
