+  if (msg) f.querySelector('p').textContent = msg;
+  window.__AC_READY = true;
+}
+
+function hasWebGL() {
+  try {
+    const c = document.createElement('canvas');
+    return !!(window.WebGL2RenderingContext && (c.getContext('webgl2') || c.getContext('webgl')));
+  } catch (e) {
+    return false;
+  }
+}
+
+function softCircle() {
+  const c = document.createElement('canvas');
+  c.width = 64;
+  c.height = 64;
+  const g = c.getContext('2d');
+  const grd = g.createRadialGradient(32, 32, 0, 32, 32, 32);
+  grd.addColorStop(0, 'rgba(255,255,255,1)');
+  grd.addColorStop(0.4, 'rgba(255,255,255,0.55)');
+  grd.addColorStop(1, 'rgba(255,255,255,0)');
+  g.fillStyle = grd;
+  g.fillRect(0, 0, 64, 64);
+  const tex = new THREE.CanvasTexture(c);
+  tex.colorSpace = THREE.SRGBColorSpace;
+  return tex;
+}
+
+function makeSky() {
+  const geo = new THREE.SphereGeometry(42, 32, 20);
+  const pos = geo.attributes.position;
+  const colors = new Float32Array(pos.count * 3);
+  const zenith = new THREE.Color(0x10151f);
+  const horizon = new THREE.Color(0xc4896c);
+  const below = new THREE.Color(0x242a30);
+  const tmp = new THREE.Color();
+  for (let i = 0; i < pos.count; i++) {
+    const y = pos.getY(i) / 42;
+    if (y >= 0) tmp.copy(horizon).lerp(zenith, Math.min(1, y * 1.55));
+    else tmp.copy(horizon).lerp(below, Math.min(1, -y * 2.2));
+    colors[i * 3] = tmp.r;
+    colors[i * 3 + 1] = tmp.g;
+    colors[i * 3 + 2] = tmp.b;
+  }
+  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
+  const mesh = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.BackSide, depthWrite: false }));
+  mesh.frustumCulled = false;
+  return mesh;
+}
+
+function panel(parent, w, h, d, mat, x, y, z, cast = true) {
+  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
+  m.position.set(x, y, z);
+  m.castShadow = cast;
+  m.receiveShadow = true;
+  parent.add(m);
+  return m;
+}
+
+function addTube(parent, points, radius, material) {
+  const curve = new PolylineCurve(points.map((p) => new THREE.Vector3(p[0], p[1], p[2])));
+  const geo = new THREE.TubeGeometry(curve, Math.max(12, points.length * 8), radius, 7, false);
+  const mesh = new THREE.Mesh(geo, material);
+  mesh.castShadow = true;
+  parent.add(mesh);
+  return mesh;
+}
+
+function makePath(stops) {
+  const curve = new PolylineCurve(stops.map((s) => new THREE.Vector3(s[0], s[1], s[2])));
+  curve.colors = stops.map((s) => new THREE.Color(s[3]));
+  return curve;
+}
+
+function makeTag(title, temp) {
+  const div = document.createElement('div');
+  div.className = temp ? 'tag temp' : 'tag';
+  const b = document.createElement('b');
+  b.textContent = title;
+  const s = document.createElement('span');
+  div.append(b, s);
+  const obj = new CSS2DObject(div);
+  obj.center.set(0.5, 1.08);
+  obj.userData.span = s;
+  obj.userData.title = b;
+  return obj;
+}
+
+function makeCoil(parent, cx, cy, cz, finW, finH, count, span) {
+  const finGeo = new THREE.BoxGeometry(finW, finH, 0.007);
+  const fins = new THREE.InstancedMesh(finGeo, MAT.fin, count);
+  for (let i = 0; i < count; i++) {
+    const z = cz + (i / (count - 1) - 0.5) * span;
+    _dummy.position.set(cx, cy, z);
+    _dummy.rotation.set(0, 0, 0);
+    _dummy.scale.set(1, 1, 1);
+    _dummy.updateMatrix();
+    fins.setMatrixAt(i, _dummy.matrix);
+  }
+  fins.castShadow = false;
+  fins.receiveShadow = true;
+  parent.add(fins);
+  for (const dy of [-finH * 0.28, 0, finH * 0.28]) {
+    const tube = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.008, span + 0.05, 8), MAT.copper);
+    tube.rotation.x = Math.PI / 2;
+    tube.position.set(cx, cy + dy, cz);
+    tube.castShadow = true;
+    parent.add(tube);
+  }
+}
+
+function makeDrops(parent, cx, cy, cz) {
+  const N = 26;
+  const geo = new THREE.SphereGeometry(0.011, 8, 6);
+  const mat = std(0xd7eef8, 0.06, 0.02, { transparent: true, opacity: 0.82 });
+  const mesh = new THREE.InstancedMesh(geo, mat, N);
+  const phases = new Float32Array(N);
+  const base = [];
+  for (let i = 0; i < N; i++) {
+    base.push({
+      x: cx + (Math.random() - 0.5) * 0.1,
+      y: cy - 0.02 - Math.random() * 0.06,
+      z: cz + (Math.random() - 0.5) * 0.42,
+      s: 0.55 + Math.random() * 0.7,
+    });
+    phases[i] = Math.random();
+    _dummy.position.set(base[i].x, base[i].y, base[i].z);
+    _dummy.scale.setScalar(base[i].s);
+    _dummy.rotation.set(0, 0, 0);
+    _dummy.updateMatrix();
+    mesh.setMatrixAt(i, _dummy.matrix);
+  }
+  mesh.instanceMatrix.needsUpdate = true;
+  parent.add(mesh);
+  return { mesh, phases, base };
+}
+
+function makeFrost(parent, cx, cy, cz) {
+  const N = 34;
