+    curve.tangentAt(s.t, _t);
+    basis(_t);
+    _p.addScaledVector(_n1, s.ox * radius);
+    _p.addScaledVector(_n2, s.oy * radius * 0.65);
+    pos[i * 3] = _p.x;
+    pos[i * 3 + 1] = _p.y;
+    pos[i * 3 + 2] = _p.z;
+    curve.colorAt(s.t, _c);
+    col[i * 3] = _c.r;
+    col[i * 3 + 1] = _c.g;
+    col[i * 3 + 2] = _c.b;
