+    pack.phases[i] += motion * (0.22 + (i % 4) * 0.03);
+    const u = pack.phases[i] % 1;
+    const b = pack.base[i];
+    _dummy.position.set(b.x, b.y - u * 0.1, b.z);
+    _dummy.rotation.set(0, 0, 0);
+    _dummy.scale.setScalar(b.s * (1 - u * 0.45));
+    _dummy.updateMatrix();
+    pack.mesh.setMatrixAt(i, _dummy.matrix);
+  }
+  pack.mesh.instanceMatrix.needsUpdate = true;
+}
+
+function bindUI() {
+  document.getElementById('btnSplit').addEventListener('click', () => {
+    if (system === 'split') return;
+    setSystem('split');
+    if (!applying) showContextual();
+  });
+  document.getElementById('btnMono').addEventListener('click', () => {
+    if (system === 'mono') return;
+    setSystem('mono');
+    if (!applying) showContextual();
+  });
+  document.getElementById('btnCool').addEventListener('click', () => {
+    if (mode === 'cool') return;
+    setMode('cool');
+    if (!applying) showContextual();
+  });
+  document.getElementById('btnHeat').addEventListener('click', () => {
+    if (mode === 'heat') return;
+    setMode('heat');
+    if (!applying) showContextual();
+  });
+  document.getElementById('btnPlay').addEventListener('click', () => {
+    playing = !playing;
+    updatePlayLabel();
+  });
+  document.getElementById('btnReset').addEventListener('click', () => {
+    viewMode = 'home';
+    goCam(CAMS.wide, reduced ? 0 : 0.9);
+  });
+  document.getElementById('btnReplay').addEventListener('click', () => {
+    tourElapsed = 0;
+    tourAuto = !reduced;
+    viewMode = 'tour';
+    if (!reduced) playing = true;
+    updatePlayLabel();
+    applyStep(0, { snap: reduced });
+  });
+  document.getElementById('btnPrev').addEventListener('click', () => {
+    tourAuto = false;
+    tourElapsed = 0;
+    applyStep(tourIndex - 1, { snap: reduced });
+  });
+  document.getElementById('btnNext').addEventListener('click', () => {
+    tourAuto = false;
+    tourElapsed = 0;
+    applyStep(tourIndex + 1, { snap: reduced });
+  });
+  const dots = document.getElementById('dots');
+  for (let i = 0; i < STEPS.length; i++) {
+    const b = document.createElement('button');
+    b.type = 'button';
+    b.setAttribute('aria-label', `Guide step ${i + 1}`);
+    b.addEventListener('click', () => {
+      tourAuto = false;
+      tourElapsed = 0;
+      viewMode = viewMode === 'user' ? 'user' : 'tour';
+      applyStep(i, { snap: reduced });
+    });
+    dots.appendChild(b);
+  }
+}
+
+function resize() {
+  const w = window.innerWidth;
+  const h = Math.max(1, window.innerHeight);
+  camera.aspect = w / h;
+  camera.fov = w < h ? 50 : 38;
+  camera.updateProjectionMatrix();
+  renderer.setSize(w, h);
+  labelRenderer.setSize(w, h);
+}
+
+function animate(now) {
+  requestAnimationFrame(animate);
+  const dt = Math.min(0.05, (now - last) / 1000) || 0;
+  last = now;
+  const motion = playing ? dt : 0;
+  simTime += motion;
+
+  if (tween) {
+    tween.u += dt / tween.dur;
+    const k = smoothstep(Math.min(1, tween.u));
+    camera.position.lerpVectors(tween.fromP, tween.toP, k);
+    controls.target.lerpVectors(tween.fromT, tween.toT, k);
+    if (tween.u >= 1) tween = null;
+  }
+  controls.update();
+
+  if (playing && tourAuto && !reduced) {
+    tourElapsed += dt;
+    if (tourElapsed > 8) {
+      tourElapsed = 0;
+      applyStep(tourIndex + 1);
+    }
+  }
+
+  const kTemp = 1 - Math.exp(-Math.max(dt, 0.001) * 2.4);
+  for (const key of Object.keys(shown)) shown[key] += (goal[key] - shown[key]) * kTemp;
+  const wobble = playing && !reduced ? Math.sin(simTime * 0.7) * 0.05 : 0;
+  setText(document.getElementById('statIn'), `${(shown.indoor + wobble).toFixed(1)}°C`);
+  setText(document.getElementById('statOut'), `${(shown.outdoor - wobble).toFixed(1)}°C`);
+  setText(document.getElementById('statSup'), `${shown.supply.toFixed(1)}°C`);
+  setText(document.getElementById('statEx'), `${shown.exhaust.toFixed(1)}°C`);
+  tags.supply.userData.span.textContent = `${shown.supply.toFixed(1)}°C`;
+  tags.exhaust.userData.span.textContent = `${shown.exhaust.toFixed(1)}°C`;
+
+  splitSlider.position.x = THREE.MathUtils.damp(splitSlider.position.x, valveTarget, 8, dt);
+  monoSlider.position.x = THREE.MathUtils.damp(monoSlider.position.x, valveTarget, 8, dt);
+
+  for (const fan of spinners) {
+    fan.userData.rotor.rotation[fan.userData.axis] += motion * fan.userData.rate;
+  }
+  for (const lv of louvers) lv.rotation.x = -0.55 + Math.sin(simTime * 1.6) * (playing && !reduced ? 0.08 : 0);
+
+  const ref = activeRef();
+  for (let i = 0; i < REF_N; i++) {
+    const s = refSeeds[i];
+    s.t += s.speed * motion;
+    if (s.t > 1) s.t -= 1;
+    ref.getPoint(s.t, _p);
+    _cam.copy(camera.position).sub(_p);
+    const len = _cam.length();
+    if (len > 0.001) _p.addScaledVector(_cam, 0.028 / len);
+    _dummy.position.copy(_p);
+    _dummy.rotation.set(0, 0, 0);
+    _dummy.scale.setScalar(s.s);
+    _dummy.updateMatrix();
+    refMesh.setMatrixAt(i, _dummy.matrix);
+    ref.colorAt(s.t, _c);
+    refMesh.setColorAt(i, _c);
+  }
+  refMesh.instanceMatrix.needsUpdate = true;
+  if (refMesh.instanceColor) refMesh.instanceColor.needsUpdate = true;
+
+  updateStream(roomPts, activeRoom(), motion, 0.055);
+  updateStream(outPts, activeOut(), motion, 0.06);
+
+  const emit = HEAT_CFG[system][mode];
+  if (motion > 0 && !reduced) {
+    heatAcc += motion;
+    while (heatAcc > 0.055) {
+      heatAcc -= 0.055;
+      spawnHeat(emit[0]);
+      spawnHeat(emit[1]);
+    }
+  }
+  const hp = heatPts.geometry.attributes.position.array;
+  const hc = heatPts.geometry.attributes.color.array;
+  for (let i = 0; i < HEAT_N; i++) {
+    if (heatLife[i] > 0) {
+      heatLife[i] -= motion;
+      heatPos[i].addScaledVector(heatVel[i], motion);
+    }
+    const alive = heatLife[i] > 0;
+    const life = alive ? heatLife[i] : 0;
+    hp[i * 3] = alive ? heatPos[i].x : 0;
+    hp[i * 3 + 1] = alive ? heatPos[i].y : -30;
+    hp[i * 3 + 2] = alive ? heatPos[i].z : 0;
+    hc[i * 3] = 1.0 * Math.min(1, life * 1.4);
+    hc[i * 3 + 1] = 0.42 * Math.min(1, life * 1.4);
+    hc[i * 3 + 2] = 0.12 * Math.min(1, life * 1.4);
+  }
+  heatPts.geometry.attributes.position.needsUpdate = true;
+  heatPts.geometry.attributes.color.needsUpdate = true;
+
+  for (const group of chevrons) {
+    const curve = group.which === 'room' ? activeRoom() : activeOut();
+    for (const cone of group.items) {
+      cone.userData.t += motion * 0.09;
+      if (cone.userData.t > 1) cone.userData.t -= 1;
+      curve.getPoint(cone.userData.t, _p);
+      curve.tangentAt(cone.userData.t, _t);
+      cone.position.copy(_p);
+      if (_t.lengthSq() > 0.5) cone.quaternion.setFromUnitVectors(_up.set(0, 1, 0), _t);
+    }
+  }
+
+  if (motion > 0) {
+    for (const pulse of pulses) {
+      pulse.userData.phase = (pulse.userData.phase + motion * 0.45) % 1;
+      const u = pulse.userData.phase;
+      pulse.scale.setScalar(0.65 + u * 1.15);
+      pulse.material.opacity = (1 - u) * 0.45;
+    }
+  }
+
+  updateDrips(splitDrops, motion);
+  updateDrips(monoDrops, motion);
+
+  const comp = system === 'split'
+    ? splitGroup.children.find((c) => c.position && c.position.x === 1.18)
+    : null;
+  if (comp && motion > 0) comp.position.y = 0.07 + Math.sin(simTime * 55) * 0.0012;
+
+  renderer.render(scene, camera);
+  labelRenderer.render(scene, camera);
+}
+
+let last = performance.now();
+
+function main() {
+  if (!hasWebGL()) {
+    showFallback('This exhibit needs WebGL. A reversible air conditioner moves heat: refrigerant circulates in a sealed loop, room air and outdoor air stay separate, and heating swaps the two heat exchangers.');
+    return;
+  }
+
+  MAT.housing = std(0xe7e2da, 0.42, 0.08);
+  MAT.fin = std(0xd5dde3, 0.28, 0.86);
+  MAT.copper = std(0xb4683c, 0.32, 1);
+  MAT.insul = std(0x2a2d31, 0.82, 0.04);
+  MAT.dark = std(0x23262b, 0.45, 0.6);
+  MAT.blade = std(0xd5dbe2, 0.32, 0.62);
+  MAT.comp = std(0x1b1e22, 0.38, 0.72);
+  MAT.brass = std(0xc6a15a, 0.3, 0.82);
+  MAT.slide = std(0xffb25e, 0.28, 0.55, { emissive: 0xff7a2a, emissiveIntensity: 0.35 });
+  MAT.sleeve = std(0x8d9398, 0.4, 0.7);
+
+  scene = new THREE.Scene();
+  scene.background = new THREE.Color(0x121722);
+  camera = new THREE.PerspectiveCamera(38, 1, 0.08, 90);
+  camera.position.set(CAMS.wide.p[0], CAMS.wide.p[1], CAMS.wide.p[2]);
+
+  renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance', alpha: false });
+  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
+  renderer.setSize(window.innerWidth, window.innerHeight);
+  renderer.outputColorSpace = THREE.SRGBColorSpace;
+  renderer.toneMapping = THREE.ACESFilmicToneMapping;
+  renderer.toneMappingExposure = 0.96;
+  renderer.shadowMap.enabled = true;
+  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
+  renderer.domElement.setAttribute('aria-label', 'Cutaway of a reversible air conditioner. Drag to orbit. Scroll or pinch to zoom.');
+  document.getElementById('view').appendChild(renderer.domElement);
+
+  if (!renderer.getContext()) {
+    showFallback('This exhibit needs WebGL. A reversible air conditioner moves heat: refrigerant circulates in a sealed loop, room air and outdoor air stay separate, and heating swaps the two heat exchangers.');
+    return;
+  }
+
+  labelRenderer = new CSS2DRenderer();
+  labelRenderer.setSize(window.innerWidth, window.innerHeight);
+  labelRenderer.domElement.id = 'labels';
+  labelRenderer.domElement.style.position = 'fixed';
+  labelRenderer.domElement.style.inset = '0';
+  labelRenderer.domElement.style.zIndex = '2';
+  labelRenderer.domElement.style.pointerEvents = 'none';
+  document.body.appendChild(labelRenderer.domElement);
+
+  try {
+    const pmrem = new THREE.PMREMGenerator(renderer);
+    scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
+    scene.environmentIntensity = 0.55;
+    pmrem.dispose();
+  } catch (err) {
+    console.warn(err);
+  }
+
+  scene.add(makeSky());
+
+  const hemi = new THREE.HemisphereLight(0xc5d2e4, 0x3a2c24, 1.7);
+  scene.add(hemi);
+  const sun = new THREE.DirectionalLight(0xd5e2ff, 4.8);
+  sun.position.set(7.5, 8.5, 4.5);
+  sun.castShadow = true;
+  sun.shadow.mapSize.set(2048, 2048);
+  sun.shadow.camera.near = 0.5;
+  sun.shadow.camera.far = 24;
+  sun.shadow.camera.left = -7;
+  sun.shadow.camera.right = 7;
+  sun.shadow.camera.top = 7;
+  sun.shadow.camera.bottom = -7;
+  sun.shadow.bias = -0.00035;
+  sun.shadow.normalBias = 0.03;
+  scene.add(sun);
+  const gallery = new THREE.DirectionalLight(0xeef2ff, 2.1);
+  gallery.position.set(2.5, 4.2, 7);
+  scene.add(gallery);
+  const spot = new THREE.SpotLight(0xffc7a1, 160, 8, 0.75, 0.55, 2);
+  spot.position.set(-1.45, 2.55, 0.35);
+  spot.target.position.set(-1.7, 0.4, 0.1);
+  scene.add(spot, spot.target);
+  const lampLight = new THREE.PointLight(0xffc9a0, 12, 3.2, 2);
+  lampLight.position.set(-1.15, 1.15, 0.95);
+  scene.add(lampLight);
+
+  buildArchitecture(scene);
+  buildSplit();
+  buildMono();
+  buildPaths();
+  buildParticles();
+
+  function mount(name, title, x, y, z, temp) {
+    const a = new THREE.Object3D();
+    a.position.set(x, y, z);
+    const tag = makeTag(title, temp);
+    a.add(tag);
+    scene.add(a);
+    tags[name] = tag;
+  }
+  mount('splitIn', 'Indoor coil', -0.55, 2.42, 0);
+  mount('splitOut', 'Outdoor coil', 1.72, 0.78, 0.15);
+  mount('splitComp', 'Compressor', 1.18, 0.48, -0.28);
+  mount('splitValve', 'Reversing valve', 1.24, 0.66, 0.2);
+  mount('monoRoom', 'Room-side coil', -0.75, 1.22, 0.1);
+  mount('monoDuct', 'Duct-side coil', -0.15, 1.28, 0.05);
+  mount('monoComp', 'Compressor', -0.62, 0.32, -0.28);
+  mount('monoValve', 'Reversing valve', -0.32, 0.48, -0.16);
+  mount('monoSep', 'Separate air streams', -0.44, 1.02, 0.42);
+  tags.monoSep.userData.span.textContent = 'room and outdoor';
+  mount('intake', 'Outdoor intake', 0.48, 0.28, -0.42);
+  tags.intake.userData.span.textContent = 'outdoor air in';
+  mount('txv', 'Expansion device', -0.32, 2.16, 0.24);
+  mount('supply', 'Supply air', -0.95, 1.78, 0.18, true);
+  mount('exhaust', 'Exhaust air', 1.42, 1.38, 0.16, true);
+
+  controls = new OrbitControls(camera, renderer.domElement);
+  controls.target.set(CAMS.wide.t[0], CAMS.wide.t[1], CAMS.wide.t[2]);
+  controls.enableDamping = true;
+  controls.dampingFactor = 0.08;
+  controls.enablePan = false;
+  controls.minDistance = 1.45;
+  controls.maxDistance = 12;
+  controls.minPolarAngle = 0.18;
+  controls.maxPolarAngle = Math.PI * 0.495;
+  controls.zoomSpeed = 0.7;
+  controls.rotateSpeed = 0.85;
+  controls.addEventListener('start', () => {
+    viewMode = 'user';
+    tween = null;
+  });
+  controls.update();
+
+  bindUI();
+  applyStep(0, { snap: true });
+  if (reduced) {
+    playing = false;
+    tourAuto = false;
+    viewMode = 'home';
+    updateDots();
+  }
+  updatePlayLabel();
+
+  renderer.domElement.addEventListener('webglcontextlost', (e) => {
+    e.preventDefault();
+    showFallback('The graphics context was lost. Reload the page to restore the exhibit.');
+  });
+
+  window.addEventListener('resize', resize);
+  if (window.visualViewport) window.visualViewport.addEventListener('resize', resize);
+  mq.addEventListener?.('change', (e) => { reduced = e.matches; });
+  resize();
+
+  document.body.classList.add('ready');
+  window.__AC_READY = true;
+  requestAnimationFrame(animate);
+}
+
+try {
+  main();
+} catch (err) {
+  console.error(err);
+  showFallback('This exhibit could not start. It needs WebGL and a network connection to load Three.js.');
+}
+</script>
+<script>
+  setTimeout(() => {
+    if (!window.__AC_READY) {
+      const f = document.getElementById('fallback');
+      f.hidden = false;
+      f.querySelector('p').textContent = 'This exhibit could not start. It needs WebGL and a network connection to load Three.js.';
+    }
+  }, 8000);
+</script>
+<noscript>
+  <div class="panel" style="position:fixed;left:50%;top:46%;transform:translate(-50%,-50%);width:min(460px,calc(100% - 40px));padding:18px;z-index:6">
+    <p>Enable JavaScript to run this exhibit.</p>
+  </div>
+</noscript>
+</body>
+</html>

