success.prevContent:
const list = await fetch('http://127.0.0.1:9333/json/list').then((r) => r.json());
const page = list.find((t) => t.type === 'page');
if (!page) throw new Error('no page target ' + JSON.stringify(list.map((t) => t.type + t.url)));
const ws = new WebSocket(page.webSocketDebuggerUrl);
const pending = new Map();
const exceptions = [];
const consoleErrors = [];
let seq = 0;
function send(method, params = {}) {
  const id = ++seq;
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
}
ws.addEventListener('message', (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const p = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) p.reject(new Error(JSON.stringify(msg.error)));
    else p.resolve(msg.result);
    return;
  }
  if (msg.method === 'Runtime.exceptionThrown') {
    const d = msg.params.exceptionDetails;
    exceptions.push((d.exception?.description || d.text || '').slice(0, 800));
  }
  if (msg.method === 'Runtime.consoleAPICalled' && (msg.params.type === 'error' || msg.params.type === 'warning')) {
    const args = (msg.params.args || []).map((a) => a.value ?? a.description ?? '').join(' ');
    consoleErrors.push(msg.params.type + ': ' + args.slice(0, 500));
  }
});
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve);
  ws.addEventListener('error', () => reject(new Error('ws')));
});
await send('Page.enable');
await send('Runtime.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 2, mobile: false });
await send('Page.navigate', { url: 'http://127.0.0.1:8765/' });
async function ev(expression) {
  const r = await send('Runtime.evaluate', { expression, returnByValue: true });
  if (r.exceptionDetails) {
    throw new Error((r.exceptionDetails.exception?.description || r.exceptionDetails.text || 'eval').slice(0, 900));
  }
  return r.result?.value;
}
for (let i = 0; i < 60; i++) {
  if (await ev('window.__AC_READY === true')) break;
  await new Promise((r) => setTimeout(r, 250));
  if (i === 59) throw new Error('ready timeout');
}
await new Promise((r) => setTimeout(r, 700));
const load = await ev(`(() => ({
  title: document.title,
  h1: document.querySelector('h1')?.textContent,
  ready: document.body.classList.contains('ready'),
  fallbackHidden: document.getElementById('fallback').hidden,
  fallback: document.getElementById('fallback').innerText.slice(0, 200),
  canvas: !!document.querySelector('#view canvas'),
  sys: document.getElementById('statSys')?.textContent || null,
  tour: document.getElementById('tourText')?.textContent || null,
  play: document.getElementById('btnPlay')?.textContent?.trim() || null
}))()`);
const clicks = [];
async function click(id) {
  await ev(`document.getElementById('${id}').click()`);
  await new Promise((r) => setTimeout(r, 160));
  clicks.push(await ev(`(() => ({
    id: '${id}',
    sys: document.getElementById('statSys').textContent,
    play: document.getElementById('btnPlay').textContent.trim(),
    tour: document.getElementById('tourText').textContent.slice(0, 100),
    step: document.getElementById('stepNum').textContent,
    split: document.getElementById('btnSplit').getAttribute('aria-pressed'),
    mono: document.getElementById('btnMono').getAttribute('aria-pressed'),
    cool: document.getElementById('btnCool').getAttribute('aria-pressed'),
    heat: document.getElementById('btnHeat').getAttribute('aria-pressed'),
    inT: document.getElementById('statIn').textContent,
    outT: document.getElementById('statOut').textContent,
    abs: document.getElementById('statAbs').textContent,
    rel: document.getElementById('statRel').textContent
  }))()`));
}
if (load.ready) {
  for (const id of ['btnMono', 'btnHeat', 'btnPlay', 'btnPlay', 'btnReset', 'btnReplay', 'btnNext', 'btnPrev', 'btnSplit', 'btnCool']) {
    await click(id);
  }
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
  await new Promise((r) => setTimeout(r, 200));
  await click('btnHeat');
  await click('btnMono');
  await ev(`document.querySelector('#dots button:nth-child(4)').click()`);
  await new Promise((r) => setTimeout(r, 150));
  clicks.push({ id: 'dot4', tour: await ev(`document.getElementById('tourText').textContent`) });
}
console.log(JSON.stringify({ load, clicks, exceptions, consoleErrors }, null, 2));
ws.close();
